import { readFileSync } from 'fs';
import { join } from 'path';
import { extractPdfLayout } from './cv-extract';
import { parseCv } from './cv-parser';

// Synthetic LinkedIn exports (test/fixtures/linkedin, regenerated by generate.js there) read through the real pdf.js extraction.
const fixture = (name: string) => join(__dirname, '../../test/fixtures/linkedin', name);

describe('LinkedIn "Save to PDF" exports (synthetic fixtures, real PDF extraction)', () => {
  it('multi-page export with a wrapped headline, grouped roles, undated school and wrapped certificates', async () => {
    const doc = await extractPdfLayout(readFileSync(fixture('career-changer.pdf')));
    const cv = parseCv(doc.text, {}, doc.lines);
    expect(cv.personalInfo.name).toBe('Leyla Mammadova');
    // The whole headline, never the About text.
    expect(cv.headline).toBe('Data Analyst at Northwind Bank | SQL, Power BI and Python | Helping retail teams turn customer data into weekly decisions');
    expect(cv.summary).toMatch(/^I started in retail operations.*product decisions directly\.$/);
    expect(cv.location).toBe('Baku, Azerbaijan');
    expect(cv.workExperience.map((e) => [e.title, e.company])).toEqual([
      ['Senior Data Analyst', 'Northwind Bank'],
      ['Data Analyst', 'Northwind Bank'],
      ['Analytics Intern', 'Northwind Bank'],
      ['Customer Insights Assistant', 'Caspian Retail Group'],
      ['Data Visualisation Freelancer', 'Self-employed'],
    ]);
    // Wrapped bullets stay whole; the next employer's name never leaks into a description.
    expect(cv.workExperience[0].description.split('\n')).toEqual([
      '• Built the branch performance dashboard in Power BI used in the weekly regional review.',
      '• Rewrote the customer churn queries in SQL, reducing the monthly refresh from four hours to forty minutes.',
      '• Mentored two junior analysts on query review and documentation.',
    ]);
    expect(cv.workExperience[2].description).toBe('Supported the analytics team with data checks and ad hoc Excel reports.');
    expect(cv.workExperience[0]).toMatchObject({ startDate: '2024-03-01T00:00:00.000Z', startPrecision: 'MONTH', endDate: null, current: true });
    // Year-only dates stay years.
    expect(cv.workExperience[4]).toMatchObject({ startDate: '2019-01-01T00:00:00.000Z', startPrecision: 'YEAR', endPrecision: 'YEAR' });
    expect(cv.education.map((e) => [e.institution, e.degree, e.fieldOfStudy])).toEqual([
      ['Azerbaijan State University of Economics (UNEC)', "Bachelor's degree", 'Finance'],
      ['Coursera', '', 'Data Science Specialization'],
      ['Code Academy', 'Certificate', 'Front-End Web Development and Responsive Design for Beginners'],
    ]);
    // An undated school has no dates and says so; nothing is filled in.
    expect(cv.education[1]).toMatchObject({ startDate: null, endDate: null, uncertain: ['startDate'] });
    expect(cv.careerSuggestions.filter((s) => s.kind === 'CERTIFICATION').map((s) => s.title)).toEqual([
      'Google Data Analytics Professional Certificate',
      'Microsoft Certified: Power BI Data Analyst Associate',
      'SQL (Advanced)',
      'Introduction to Machine Learning with Python and Scikit-learn for Analysts',
    ]);
    expect(cv.careerSuggestions.filter((s) => s.kind === 'AWARD').map((s) => s.title)).toEqual(['Best Graduation Project Award, Faculty of Finance']);
    expect(JSON.stringify(cv)).not.toMatch(/Page \d of \d/);
  });

  it('reads the same export from its text alone (no font sizes)', async () => {
    const doc = await extractPdfLayout(readFileSync(fixture('career-changer.pdf')));
    const cv = parseCv(doc.text);
    expect(cv.personalInfo.name).toBe('Leyla Mammadova');
    expect(cv.workExperience.map((e) => e.company)).toEqual(['Northwind Bank', 'Northwind Bank', 'Northwind Bank', 'Caspian Retail Group', 'Self-employed']);
    expect(cv.education.map((e) => e.institution)).toEqual(['Azerbaijan State University of Economics (UNEC)', 'Coursera', 'Code Academy']);
  });

  it('student export with no Summary: identity, roles at a university employer, school dates with month and year precision', async () => {
    const doc = await extractPdfLayout(readFileSync(fixture('student.pdf')));
    const cv = parseCv(doc.text, {}, doc.lines);
    expect(cv.personalInfo.name).toBe('Tural Example');
    expect(cv.headline).toBe('Computer Science Student at ADA University');
    expect(cv.summary).toBe('');
    expect(cv.workExperience.map((e) => [e.title, e.company])).toEqual([
      ['Software Engineering Intern', 'Example Software LLC'],
      ['Teaching Assistant, Introduction to Programming', 'ADA University'],
    ]);
    expect(cv.education[0]).toMatchObject({ institution: 'ADA University', degree: 'Bachelor of Science - BS', fieldOfStudy: 'Computer Science', startPrecision: 'MONTH' });
    expect(cv.education[1]).toMatchObject({ institution: 'Lyceum No. 6', degree: 'High School Diploma', startPrecision: 'YEAR', endPrecision: 'YEAR' });
    expect(cv.careerSuggestions.filter((s) => s.kind === 'CERTIFICATION')).toHaveLength(5);
  });
});

